    if iscommentline(line):
        line = line.strip()
    else:
        line = line.rstrip()
    if not line:
        return None, None
    if line[0] == "[":
        realline = line
        for c in COMMENTCHARS:
            line = line.split(c)[0].rstrip()
        if line[-1] == "]":
            return None, line[1:-1]
        return line.strip(), realline.strip()
    elif line[0].isspace():
        try:
            name, value = line.split("=", 1)
            if ":" in name:
                raise ValueError()
        except ValueError:
